Lemma vis_ok_1RB1LD_1LC0RC_1LA1RC_0LB0LA : forall r t, ~ In t pins_1RB1LD_1LC0RC_1LA1RC_0LB0LA -> 0 < r ->
  r < 1 + 1 ->
