(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB1LD_1LC1RB_1RA1LA_0RB0LC : NeverQuasiHaltsTr tm_1RB1LD_1LC1RB_1RA1LA_0RB0LC.
Proof.
  apply (boardph_neverqhtr tm_1RB1LD_1LC1RB_1RA1LA_0RB0LC pins_1RB1LD_1LC1RB_1RA1LA_0RB0LC FAM 1
                           iarm_1RB1LD_1LC1RB_1RA1LA_0RB0LC 0 1
                           farm_1RB1LD_1LC1RB_1RA1LA_0RB0LC 1 1
                           fm1_1RB1LD_1LC1RB_1RA1LA_0RB0LC fm2_1RB1LD_1LC1RB_1RA1LA_0RB0LC 0 vis_1RB1LD_1LC1RB_1RA1LA_0RB0LC
                           [0] 0 21).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
