Lemma farm_sound_1RB1LD_1RC1LA_0LA1RC_1LB0RC : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_1RB1LD_1RC1LA_0LA1RC_1LB0RC r ph).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  {
    destruct ph as [|ph].
    { eapply arm_sound; [exact rules_sound_1RB1LD_1RC1LA_0LA1RC_1LB0RC | exact ok_farm1_0_1RB1LD_1RC1LA_0LA1RC_1LB0RC]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma farm_lhs_1RB1LD_1RC1LA_0LA1RC_1LB0RC : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_lhs (farm_1RB1LD_1RC1LA_0LA1RC_1LB0RC r ph)
    = cls_conf FAM (run_side FAM (fm_b FAM - 1) r (astride 1 1 r)
                      0 ph [] []).
