Import BBBT4_Statement.
Import WrapTr LadderCheckTr.
Import LapGlueTr.
Import LadderCheckLiftTr.
Import ListNotations.

Definition mk_1RB1RB_0LC0RD_1RD1LC_1LC1RA (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_1RB1RB_0LC0RD_1RD1LC_1LC1RA.

(** 1RB1RB_0LC0RD_1RD1LC_1LC1RA *)
Definition tm_1RB1RB_0LC0RD_1RD1LC_1LC1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S1 DR StB
  | StB, S0 => mk S0 DL StC
  | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S1 DR StD
  | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S1 DL StC
  | StD, S1 => mk S1 DR StA
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB1RB_0LC0RD_1RD1LC_1LC1RA : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB1RB_0LC0RD_1RD1LC_1LC1RA pins_1RB1RB_0LC0RD_1RD1LC_1LC1RA).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1RB_0LC0RD_1RD1LC_1LC1RA : Fam := mkFam 2 [[S1;S1;S0];[S1;S1;S1]] [] [[S1;S1;S1]] Binary 1 [mkFill 1 [1] 0 [] 0] StB S0 true [].
Local Notation FAM := fam_1RB1RB_0LC0RD_1RD1LC_1LC1RA.

(** ** The ladder, as DATA

    2 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1RB_0LC0RD_1RD1LC_1LC1RA : list (LRule * list rstep) :=
  [(mkLRule (mkC StC (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1;S1] [] 0 0 [])) (mkC StD (mkS [S0;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)])].
Local Notation lad := lad_1RB1RB_0LC0RD_1RD1LC_1LC1RA.

Definition rules_1RB1RB_0LC0RD_1RD1LC_1LC1RA : list LRule := map fst lad.
Local Notation rules := rules_1RB1RB_0LC0RD_1RD1LC_1LC1RA.

Lemma ladder_ok_1RB1RB_0LC0RD_1RD1LC_1LC1RA : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1RB_0LC0RD_1RD1LC_1LC1RA : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1RB_0LC0RD_1RD1LC_1LC1RA. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
