          (mkC StB (mkS [S1;S1;S1;S1;S1;S0;S1;S1;S0;S1;S1;S0;S1;S1;S0;S1;S1;S0;S1;S1;S0;S1;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 48.
