  | 1, (StC, S1) => [SWin 1]
  | 1, (StD, S0) => [SWin 3;SCycL 3 0;SWin 3;SWinL 5;SCycR 3;SWin 3]
  | 1, (StD, S1) => [SWin 3;SCycL 3 0;SWinL 5]
  | _, _ => []
  end.

