   (mkLRule (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1;S0;S1] [] 0 0 [])) (mkC StA (mkS [S1;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)])].
