Lemma ladder_ok_1RB1RB_1LC1RD_0RD1LC_1RA0LC : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1RB_1LC1RD_0RD1LC_1RA0LC : Forall (RuleSound tm false false) rules.
