            ch_iarm0_0_1RB1RB_1RC0LA_0LD0RA_1RA1LD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1RB_1RC0LA_0LD0RA_1RA1LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1RB_1RC0LA_0LD0RA_1RA1LD
  | _, _ => iarm0_0_1RB1RB_1RC0LA_0LD0RA_1RA1LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1RB_1RC0LA_0LD0RA_1RA1LD : LRule :=
